const dealResult = $input.item.json.body?.result || {};
const custom = dealResult.values?.custom || {};

// Функция для поиска поля
function getFieldValue(fieldName) {
  for (const key in custom) {
    const field = custom[key];
    if (field?.name_id === fieldName || (field?.name && field.name.includes(fieldName))) {
      return field?.value || null;
    }
  }
  return null;
}

// Поиск вопроса клиента по ключевым словам
function findClientQuestion() {
  const keyMarkers = ['вопрос клиента', 'client question', 'client_question', 'question', 'вопрос'];
  const candidates = [];

  for (const key in custom) {
    const field = custom[key];
    const nm = String(field?.name || '').toLowerCase();
    if (nm && keyMarkers.some(m => nm.includes(m))) {
      const val = String(field?.value || '').trim();
      if (val && val.toLowerCase() !== 'success' && val.toLowerCase() !== 'ok') {
        candidates.push(val);
      }
    }
  }

  return candidates.length > 0 ? candidates.reduce((a, b) => a.length > b.length ? a : b) : 'Первое сообщение не найдено';
}

// Извлекаем все данные
const clientInfo = {
  first_name: getFieldValue('crm_1035789') || 'Unknown',
  last_name: getFieldValue('crm_1035792') || 'Unknown',
  salutation: getFieldValue('crm_1035786') || 'Unknown',
  date_of_birth: getFieldValue('crm_1037898') || null,
  question_from_client: findClientQuestion(),
  nationality: getFieldValue('crm_1036419') || 'Unknown',
  country_of_residence: getFieldValue('crm_1036422') || 'Unknown',
  citizenship: getFieldValue('crm_1039314') || 'Unknown',
  residence_country: getFieldValue('crm_1041756') || 'Unknown',
  relocation_timeline: getFieldValue('crm_1045338') || 'Unknown',
  visa_type: getFieldValue('crm_1045341') || 'Unknown',
  product_interest: getFieldValue('crm_1045344') || 'Unknown',
  timezone: dealResult.values?.service?.timezone?.value || 'UTC',
  region: dealResult.values?.service?.ip_place_id?.value || null,
  meeting_format: getFieldValue('crm_1039044') || 'Unknown',
  meeting_date: getFieldValue('crm_1039041') || null
};

const prevData = $('Extract Deal Data').item.json;

return {
  ...prevData,
  client_info: clientInfo,
  client_full_name: `${clientInfo.salutation} ${clientInfo.first_name} ${clientInfo.last_name}`.trim(),
  first_message_from_client: clientInfo.question_from_client
};

// Таблица соответствий employee_id -> email менеджера
const MANAGER_EMAIL_MAPPING = {
  "1137861": "e.novik@arkvostok.com",
  // Добавь других менеджеров:
  // "employee_id": "manager@yandex.ru",
};

const employeeId = String($input.item.json.employee_id || '');
const managerEmail = MANAGER_EMAIL_MAPPING[employeeId];
const finalEmail = managerEmail || $env.MAIL_ADRESS || 'default@yandex.ru';

return {
  ...($input.item.json),
  manager_email: finalEmail,
  manager_email_source: managerEmail ? 'mapping' : 'default'
};

// Объединяем все письма из INBOX и Sent в единую хронологическую историю
const crmData = $('Map Manager Email').item.json;

// Получаем письма из обоих источников
const allEmailsData = $input.all();
const allEmails = allEmailsData
  .map(item => {
    const dateStr = item.json.date || new Date().toISOString();
    let timestamp = 0;
    try {
      timestamp = new Date(dateStr).getTime() / 1000;
    } catch (e) {
      timestamp = 0;
    }

    return {
      from: item.json.from || '',
      to: item.json.to || '',
      subject: item.json.subject || 'No subject',
      date: dateStr,
      body: item.json.textPlain || item.json.html || item.json.text || '',
      timestamp: timestamp,
      direction: (item.json.from || '').includes(crmData.client_email) ? 'FROM_CLIENT' : 'TO_CLIENT'
    };
  })
  .sort((a, b) => a.timestamp - b.timestamp);

// Форматируем историю переписки
const emailHistory = allEmails.map((email, index) => {
  const direction = email.direction === 'FROM_CLIENT' ? 'CLIENT' : 'MANAGER';
  return `
=== EMAIL #${index + 1} [${direction}] ===
From: ${email.from}
To: ${email.to}
Date: ${email.date}
Subject: ${email.subject}

${email.body}
========================
`;
}).join('\n');

return {
  ...crmData,
  email_history: emailHistory,
  email_count: allEmails.length,
  last_email_date: allEmails[allEmails.length - 1]?.date || 'N/A'
};

// ЗАПОЛНИ ПРИМЕРЫ из 1.txt, 2.txt, 3.txt
const EXAMPLE_TEMPLATES = `
=== ПРИМЕР 1 ===
(Вставь сюда содержимое 1.txt - пример идеального ответа менеджера)

=== ПРИМЕР 2 ===
(Вставь сюда содержимое 2.txt)

=== ПРИМЕР 3 ===
(Вставь сюда содержимое 3.txt)
`;

// Системный промпт
const SYSTEM_PROMPT = `Ты — менеджер MovetoRussia.com. Пишешь клиенту на английском, тон — живой человек, не бот: вежливо, спокойно, по делу.

Главная бизнес-цель: в перспективе мягко вывести диалог на созвон по телефону.

Страны, из которых возможен переезд по shared values visa: страны ЕС, США, Канада, Австралия, все недружественные для России государства.

Этапы воронки:
1. Первый контакт
2. Получили ответ
3. Предложили созвон

Ты сейчас отвечаешь на первый контакт. Не нужно прямо сейчас предлагать созвон. Ты лишь отвечаешь на вопросы клиента и удерживаешь его.

Правила: ответь на вопросы клиента из переписки; не выдумывай факты, ссылки, сроки и гарантии; не обещай 100% результат; не упоминай ИИ/автоматизацию; чувствительные темы — мягко и обтекаемо, без отпугивания.

Сначала кратко на русском (2–4 предложения): что ты понял из ситуации и какой ход к созвону.
Потом готовое письмо целиком на английском (тема + текст, как в реальном email).

Предложи текст следующего письма клиенту.`;

const data = $input.item.json;

// Собираем финальный промпт
const finalPrompt = `
${SYSTEM_PROMPT}

=== ИНФОРМАЦИЯ О КЛИЕНТЕ ===
Email: ${data.client_email}
Имя: ${data.client_full_name}
Страна проживания: ${data.client_info?.country_of_residence}
Национальность: ${data.client_info?.nationality}
Тайм-зона: ${data.client_info?.timezone}
Когда хочет переехать: ${data.client_info?.relocation_timeline}
Тип визы: ${data.client_info?.visa_type}

=== CRM ДАННЫЕ ===
ID сделки: ${data.deal_id}
ID воронки: ${data.pipeline_id}
ID этапа: ${data.stage_id}
ID менеджера: ${data.employee_id}

=== ПЕРВОЕ ОБРАЩЕНИЕ КЛИЕНТА (с сайта) ===
${data.first_message_from_client}

=== ИСТОРИЯ ПЕРЕПИСКИ (${data.email_count} писем) ===
${data.email_history}

=== ПРИМЕРЫ ИДЕАЛЬНЫХ ОТВЕТОВ ===
${EXAMPLE_TEMPLATES}

=== ЗАДАЧА ===
Проанализируй всю историю переписки выше и напиши следующее письмо клиенту ${data.client_email}.
Ответь на все его вопросы. Будь вежлив, предсказуем и заботлив.
`;

return {
  ...data,
  final_prompt: finalPrompt,
  prompt_length: finalPrompt.length
};
